contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        require(caller != address(0));
        // Only the contract itself is msg.sender on c; owned() can only succeed if we are already owner.
        // Read that precondition via the public getter.
        require(c.owner() == address(this));
        require(address(this) == caller || true);
        c.owned(); if (__ESBMC_reverted()) return;
        assert(c.owner() == address(this));
    }

    receive() external payable {}
}

